// Turns the pasted list into one call per number
const toE164 = (value) => {
  const text = String(value || '').trim();
  const digits = text.replace(/\D/g, '');
  if (text.startsWith('+') && digits.length >= 8) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return null;
};
const escapeXml = (s) => String(s).replace(/[<>&'"]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));

const form = $input.first().json;
const message = String(form['Message to say'] || '').trim() || 'Hello, this is a call from our team.';
const agentPhone = toE164(form['Your phone (answered calls connect here)']);

const seen = new Set();
const calls = [];
for (const line of String(form['Phone numbers'] || '').split(/\r?\n/)) {
  if (!line.trim()) continue;
  // Each line: "+15551234567" or "John, +15551234567"
  const parts = line.split(',');
  const phone = toE164(parts[parts.length - 1]);
  const name = parts.length > 1 ? parts.slice(0, -1).join(',').trim() : '';
  if (!phone || seen.has(phone)) continue;
  seen.add(phone);

  const greeting = name ? `Hello ${name}. ${message}` : message;
  let twiml = `<Response><Say>${escapeXml(greeting)}</Say>`;
  if (agentPhone) twiml += `<Dial>${agentPhone}</Dial>`;
  twiml += '</Response>';
  calls.push({ json: { name, phone, twiml } });
}

if (calls.length === 0) throw new Error('No valid phone numbers found. Use +country code, e.g. +15551234567');
return calls;
